mapper.select:
SELECT

FROM conversations c
WHERE c.id = #{id}

SELECT

FROM conversations c
WHERE c.owner_id = #{ownerId}
ORDER BY c.last_message_at DESC, c.id DESC
LIMIT #{size} OFFSET #{offset}

SELECT

FROM conversations c
WHERE c.id = #{id}
  AND c.owner_id = #{ownerId}

SELECT

FROM conversations c
WHERE c.owner_id = #{ownerId}
  AND c.type = #{type}
  AND c.related_type = #{relatedType}
  AND c.related_id = #{relatedId}
ORDER BY c.id ASC
LIMIT 1

SELECT c.* FROM conversations c
WHERE c.owner_id = #{ownerId} AND c.type = #{type}
  AND c.related_type = #{relatedType} AND c.related_id = #{relatedId}
LIMIT 1 FOR UPDATE
